mapper.sql:
WHERE dict_type_id = #{dictTypeId}

  AND (label LIKE CONCAT('%', #{keyword}, '%') OR value LIKE CONCAT('%', #{keyword}, '%'))


  AND status = #{status}

mapper.select:
SELECT id, dict_type_id AS dictTypeId, parent_id AS parentId, label, value, status, sort_order AS sortOrder, remark FROM dict_items
ORDER BY sort_order ASC, id ASC
LIMIT #{limit} OFFSET #{offset}
